using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData no longer allows non-deterministic values
        // like DateTime.UtcNow. Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "ShopDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: Cosmos provider now uses "$type" as the
        // default discriminator property instead of "Discriminator".
        // For existing documents that already use "Discriminator", explicitly
        // configure it to keep backward compatibility.
        modelBuilder.Entity<Product>()
            .HasDiscriminant<string>("Discriminator")
            .HasValue<Product>("Product")
            .HasValue<DiscountedProduct>("DiscountedProduct");

        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

// --- Cosmos DB query service demonstrating sync-to-async migration ---

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O is no longer supported by
    // the Cosmos DB provider. All queries must use async methods.
    // Before (would throw InvalidOperationException in EF Core 9):
    //   var products = db.Products.ToList();
    // After:
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        return await db.Products.ToListAsync();
    }

    // Before (sync Single):
    //   var product = db.Products.Single(p => p.Id == id);
    // After:
    async Task<Product> GetProductByIdAsync(CosmosDbContext db, string id)
    {
        return await db.Products.SingleAsync(p => p.Id == id);
    }
}

